// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address operator, uint256 tokenId, bytes calldata data) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.prank(caller);
        bytes4 returned = c.onERC721Received(operator, address(0), tokenId, data);
        assertTrue(returned == ERC721TokenReceiver.onERC721Received.selector);
    }
}

abstract contract ERC721TokenReceiver {
    function onERC721Received(address, address, uint256, bytes calldata) external virtual returns (bytes4);
}
